def find_longest_repeating_subseq(s):
    n = len(s)
    # dp[i][j] = length of longest repeating subsequence in s[0:i] and s[0:j]
    # where the two subsequences don't have same characters at same positions
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i != j and s[i - 1] == s[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
