    # This is equivalent to: (L - A) / M <= k <= (R - A) / M

    # Find the smallest k such that A + k*M >= L
    # k >= (L - A) / M
    # Since k must be integer, k_min = ceil((L - A) / M)

    # Find the largest k such that A + k*M <= R
    # k <= (R - A) / M
    # k_max = floor((R - A) / M)

    def ceil_div(a, b):
        # ceil(a/b) for positive b
        if a >= 0:
            return (a + b - 1) // b
        else:
            return -((-a) // b)

    def floor_div(a, b):
        # floor(a/b) for positive b
        if a >= 0:
            return a // b
        else:
            return -((-a + b - 1) // b)

    k_min = ceil_div(L - A, M)
    k_max = floor_div(R - A, M)

