import sys
from itertools import combinations

def can_place(tiles, H, W):
    """
    Check if the given list of tiles can exactly cover an H x W grid.
    Each tile is (a, b) and can be rotated (so (a,b) or (b,a)).
    We use backtracking to try to place tiles in the grid.
    """
    # We'll represent the grid as a 2D list of 0s (empty) and 1s (covered)
    grid = [[0] * W for _ in range(H)]

    # Sort tiles by area descending to prune earlier
    tiles_sorted = sorted(tiles, key=lambda x: x[0] * x[1], reverse=True)

    def backtrack(idx):
        if idx == len(tiles_sorted):
            # Check if all cells are covered
            for i in range(H):
                for j in range(W):
                    if grid[i][j] == 0:
                        return False
            return True

        a, b = tiles_sorted[idx]
        # Try both orientations
        for (ta, tb) in [(a, b), (b, a)]:
            if ta > H or tb > W:
                continue
            # Try all positions
            for i in range(H - ta + 1):
                for j in range(W - tb + 1):
                    # Check if this placement is valid (all cells are empty)
                    valid = True
                    for di in range(ta):
                        for dj in range(tb):
                            if grid[i + di][j + dj] != 0:
                                valid = False
                                break
                        if not valid:
                            break
                    if not valid:
                        continue
                    # Place the tile
                    for di in range(ta):
                        for dj in range(tb):
                            grid[i + di][j + dj] = 1
                    # Recurse
                    if backtrack(idx + 1):
                        return True
                    # Undo
                    for di in range(ta):
                        for dj in range(tb):
                            grid[i + di][j + dj] = 0
        return False

    return backtrack(0)

def solve():
