    if not data:
        print("No")
        return

    it = iter(data)
    N = int(next(it))
    H = int(next(it))
    W = int(next(it))

    tiles = []
    for _ in range(N):
        a = int(next(it))
        b = int(next(it))
        tiles.append((a, b))

    total_area = H * W

    # Try all subsets of tiles
    # Since N <= 7, there are at most 2^7 = 128 subsets
    for r in range(1, N + 1):
        for subset in combinations(tiles, r):
            area_sum = sum(a * b for a, b in subset)
            if area_sum != total_area:
                continue
            if can_place(list(subset), H, W):
                print("Yes")
                return

    print("No")

