    nums = list(map(int, data.strip('[]').split(',')))
    n = len(nums)
    MOD = 10**9 + 7

    # Create a graph where edge i->j exists if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0
    # We need to count Hamiltonian paths in this graph

    # Use bitmask DP
    # dp[mask][i] = number of ways to arrange elements in mask ending at element i
    size = 1 << n

    # Precompute adjacency
    adj = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j:
                if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0:
                    adj[i][j] = True

    # dp[mask][i]
    dp = [[0] * n for _ in range(size)]

    # Base case: single element
    for i in range(n):
        dp[1 << i][i] = 1

    # Transition
    for mask in range(size):
        for i in range(n):
            if dp[mask][i] == 0:
                continue
            if not (mask & (1 << i)):
                continue
            for j in range(n):
                if mask & (1 << j):
                    continue
                if adj[i][j]:
                    new_mask = mask | (1 << j)
                    dp[new_mask][j] = (dp[new_mask][j] + dp[mask][i]) % MOD

    # Sum up all dp[full_mask][i] for all i
    full_mask = size - 1
    result = sum(dp[full_mask][i] for i in range(n)) % MOD
    print(result)

